# ==============================================================================# IOTEC MISSION CONTROL# 010_MAESTRO_CORE.py# ==============================================================================import jsonimport sqlite3from pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"CONFIG = ROOT / "MISSION_CONTROL" / "config"MAESTRO = CONFIG / "maestro_status.json"conn = sqlite3.connect(DB, timeout=30)cur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS maestro_history(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    action TEXT,    status TEXT)""")conn.commit()cur.execute(    """    INSERT INTO maestro_history(        timestamp,        action,        status    )    VALUES(?,?,?)    """,    (        datetime.now().isoformat(),        "SYSTEM_BOOT",        "SUCCESS"    ))conn.commit()cur.execute("SELECT COUNT(*) FROM maestro_history")history = cur.fetchone()[0]status = {    "timestamp": datetime.now().isoformat(),    "engine": "MAESTRO",    "status": "ONLINE",    "history": history,    "database": "CONNECTED"}with open(MAESTRO, "w", encoding="utf-8") as f:    json.dump(status, f, indent=4, ensure_ascii=False)print("=" * 80)print("MAESTRO CORE")print("=" * 80)print(f"STATUS........: {status['status']}")print(f"HISTORY.......: {history}")print(f"DATABASE......: CONNECTED")print("=" * 80)conn.close()

